package com.payshield.api; import com.payshield.domain.Payment; import java.math.BigDecimal; import java.util.UUID; public record PaymentResponse(UUID paymentId,BigDecimal amount,String currency,String merchantReference,String customerId,String status,String failureReason){ public static PaymentResponse from(Payment p){return new PaymentResponse(p.getId(),p.getAmount(),p.getCurrency(),p.getMerchantReference(),p.getCustomerId(),p.getStatus().name(),p.getFailureReason());} }
